def _security() -> None:
    ex = op.execute
    ex("GRANT USAGE ON SCHEMA rl TO rl_app")

    # Global identity tables (no tenant_id): the app needs them for login.
    for table in ("users", "sessions", "email_tokens", "mfa_factors", "recovery_codes"):
        grant_app(ex, table)
    # Platform admins are created only through the owner-role CLI.
    grant_app(ex, "platform_admins", "SELECT")

    # Tenant tables.
    for table in ("invites", "idempotency_keys", "notifications", "notification_preferences"):
        enable_tenant_rls(ex, table)
        grant_app(ex, table)
    enable_tenant_rls(ex, "support_access_grants", platform_read=True)
    grant_app(ex, "support_access_grants")
    enable_tenant_rls(ex, "memberships", platform_read=True)
    ex(f"CREATE POLICY own_memberships ON rl.memberships FOR SELECT USING (user_id = {USER})")
    grant_app(ex, "memberships")

    ex("ALTER TABLE rl.tenants ENABLE ROW LEVEL SECURITY")
    ex(f"CREATE POLICY tenant_self ON rl.tenants USING (id = {TENANT}) WITH CHECK (id = {TENANT})")
    ex(
        "CREATE POLICY member_read ON rl.tenants FOR SELECT USING (EXISTS ("
        "SELECT 1 FROM rl.memberships m WHERE m.tenant_id = tenants.id "
        f"AND m.user_id = {USER} AND m.status = 'active'))"
    )
    ex(f"CREATE POLICY platform_all ON rl.tenants USING ({PLATFORM}) WITH CHECK ({PLATFORM})")
    grant_app(ex, "tenants", "SELECT, INSERT, UPDATE")

    ex("ALTER TABLE rl.jobs ENABLE ROW LEVEL SECURITY")
    ex(
        f"CREATE POLICY tenant_or_platform ON rl.jobs USING (tenant_id = {TENANT} "
        f"OR (tenant_id IS NULL AND {PLATFORM})) WITH CHECK (tenant_id = {TENANT} "
        f"OR (tenant_id IS NULL AND {PLATFORM}))"
    )
    # Account emails (reset, verify, security notices) are queued before any tenant
    # context exists; only that job type may be inserted without one.
    ex(
        "CREATE POLICY system_email_insert ON rl.jobs FOR INSERT "
        "WITH CHECK (tenant_id IS NULL AND type = 'send_email')"
    )
    ex(f"CREATE POLICY platform_read ON rl.jobs FOR SELECT USING ({PLATFORM})")
    ex(
        f"CREATE POLICY platform_update ON rl.jobs FOR UPDATE USING ({PLATFORM}) WITH CHECK ({PLATFORM})"
    )
    grant_app(ex, "jobs")

    # Audit log: append-only for the app role (SPEC §4.12).
    ex("ALTER TABLE rl.audit_events ENABLE ROW LEVEL SECURITY")
    ex(
        f"CREATE POLICY tenant_isolation ON rl.audit_events USING (tenant_id = {TENANT}) "
        f"WITH CHECK (tenant_id = {TENANT})"
    )
    ex(
        f"CREATE POLICY platform_chain ON rl.audit_events USING (tenant_id IS NULL AND {PLATFORM}) "
        f"WITH CHECK (tenant_id IS NULL AND {PLATFORM})"
    )
    grant_app(ex, "audit_events", "SELECT, INSERT")

    # Invite acceptance happens before any tenant context exists. This function reveals
    # only the tenant id of a live invite whose token hash the caller already knows.
    ex(
        """
        CREATE FUNCTION rl.invite_tenant(p_hash bytea) RETURNS uuid
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = rl, pg_temp AS $$
          SELECT tenant_id FROM rl.invites
          WHERE token_hash = p_hash AND accepted_at IS NULL AND revoked_at IS NULL
            AND expires_at > now()
        $$
        """
    )
    ex("REVOKE ALL ON FUNCTION rl.invite_tenant(bytea) FROM PUBLIC")
    ex("GRANT EXECUTE ON FUNCTION rl.invite_tenant(bytea) TO rl_app")


